def load_observations(raw_observations: list) -> list:
    return raw_observations


def load_protocol(raw_protocol: dict) -> dict:
    return raw_protocol


def normalize_protocol(protocol: dict) -> dict:
    return {"scale": protocol["scale"], "offset": protocol["offset"]}


def evaluate(observations: list, settings: dict, candidate: dict) -> dict:
    return {"score": sum(observations) * settings["scale"] + settings["offset"], "candidate": candidate["name"], "phase": candidate["phase"]}


def workflow(raw_observations: list, raw_protocol: dict, candidate: dict) -> dict:
    observations = load_observations(raw_observations)
    protocol = load_protocol(raw_protocol)
    settings = normalize_protocol(protocol)
    report = evaluate(observations, settings, candidate)
    return report

